export function csvToMarkdown(csvText) {
  // 空文字チェック
  if (!csvText || csvText.trim() === "") {
    return "";
  }

  // 行に分割（改行コードの違いを吸収）
  const rows = csvText.trim().split(/\r\n|\n|\r/);

  if (rows.length === 0) return "";

  // 各行をカンマで分割してセルの配列に変換
  const table = rows.map((row) => parseCSVRow(row));

  // 列数を統一（最大列数に合わせる）
  const colCount = Math.max(...table.map((row) => row.length));
  const normalized = table.map((row) => {
    while (row.length < colCount) row.push("");
    return row;
  });

  // Markdown生成
  const header = normalized[0];
  const separator = header.map(() => "---");
  const body = normalized.slice(1);

  const toRow = (cells) => `| ${cells.join(" | ")} |`;

  const lines = [
    toRow(header),
    toRow(separator),
    ...body.map(toRow),
  ];

  return lines.join("\n");
}

// カンマ区切りの1行をパース（ダブルクォート対応）
function parseCSVRow(row) {
  const cells = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < row.length; i++) {
    const char = row[i];

    if (char === '"') {
      if (inQuotes && row[i + 1] === '"') {
        // ダブルクォートのエスケープ（"" → "）
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === "," && !inQuotes) {
      cells.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }

  cells.push(current.trim());
  return cells;
}
